from pathlib import Path
import json
B=Path(__file__).resolve().parents[2];C=B/'chapters';log=B/'audit/20260924_整书统稿/正文改动记录.json';changes=json.loads(log.read_text())
def edit(name,fn,why):
 p=C/name;s=p.read_text();t=fn(s);assert t!=s;p.write_text(t);changes.append({'chapter':name,'purpose':why})
def before(s,a,n):
 assert s.count(a)==1;return s.replace(a,n.strip()+'\n\n'+a,1)
def section(s,a,b,n):
 i=s.index(a);j=s.index(b,i);return s[:i]+n.strip()+'\n\n'+s[j:]
edit('01_法国的能力与代价.md',lambda s:s.replace('地方支出、征收成本、驻军和旧债必须一起调整。〔法14〕','地方支出、征收成本、驻军和旧债必须一起调整。〔法13〕').replace('约40万至45万法国常备军、规模可兑现的盟军、受约束的海军扩建和可持续地方财政，构成一个有史实尺度支持的起点。','当收入越过整固门槛，约40万至45万法国常备军、规模可兑现的盟军、受约束的海军扩建和可持续地方财政，才构成有史实尺度可参照的目标。'),'修正引注与章末兵额条件')
edit('02a_英国海权与和平_国家财政与社会.md',lambda s:before(s,'## 三、信用危机为什么没有自动变成国家破产','''### 5. 海上停战要停止哪些事

保留西班牙王朝只移除一项障碍，仍不足以让英国解除海上压力。本书的主线选择先争取一个可续订的海上停战，再谈全面承认大陆秩序。停战至少要明确五件事：停止针对缔约方普通商船的捕获；终止相应封锁公告及一般性报复扣货；清算旧扣押与俘虏；公布军需禁运、船旗和货物检查规则；设置违约交涉和恢复敌对行动的通知程序。军舰获准训练航行，并不取得任意进入对方港口或殖民地的权利。

这是参照亚眠和约财产条款及1806年交涉构件提出的方案，不是发现了一份未签署的停战文本。英国得到的是可检查的安全限制，法国得到的是贸易和训练，而非英国承认所有法国要求。协定若只发放少量许可证、海军仍捕船封港，应归入“持续海战”，不得享用第三章武装和平的全部收益。〔英政4〕〔导5〕

谈判失败后的主线退路也应明确：维持大陆防御、保护中立贸易并保留远洋骚扰，推迟大规模海军追平与跨洋护航承诺。法国仍可能保住霸权，却要以较低海上收入、更慢人员训练和更脆弱的盟国贸易为代价。胜利的范围随之收窄，不用“事实上和平”掩盖仍在发生的战争。'''),'界定停战法律与实际执行，区分持续海战')
edit('02a_英国海权与和平_国家财政与社会.md',lambda s:before(s,'## 七、市场是否预见了拿破仑的胜败','''### 4. 英国会更穷，还是只不再一枝独秀

在本书选定的开放与有限停战主线下，**不把英国截至1848年的绝对产出低于真实历史作为基本结论**。少付大陆战争费用、恢复欧洲市场和原料航路，同样有利于英国；法国在大陆发展较快，则可能降低英国的相对份额。英国继续变富与英国不再独占增长优势，可以同时发生。

若比较的是“同一英国遭遇长期封锁”与“同一英国得到开放和平”，前者明显较差；若比较的是反事实开放和平与真实历史的战时及战后道路，方向还取决于市场、军费和技术转移，现有增长试算跨过1，已经排除了单向断言。若比较法国扩大的总量与英国人均效率，则还须分开人口和生产率。前列出口、工业、煤铁和福利模型分别回答不同问题，不能拼成英国已经衰退的一张总成绩单。

这使两国关系更难而非更简单。一个更富裕的英国有能力维持海军，一个更富裕的大陆也更有理由拒绝被封锁。和平成立的根据是双方目标有限，不是对手终将贫穷到放弃选择。'''),'统一英国绝对产出、相对份额与比较基准')
edit('02b_英国海权与和平_舰队海峡与帝国.md',lambda s:before(s,'### 2. 原模型的有用之处：让条件与结果同时出现','''这里必须进一步作取舍。第一章选定的常态海军支出，是整固档每年1.45亿、后续升级档1.65亿法郎；第三节以下保留的1.95亿及更高投入舰队模型，不再充当它的预测值。**本书对1830年的工作判断，是争取约相当于英国一半至三分之二的年度可动员主力舰吨位；接近九成列为高投入、较完整基地和有利英国反应同时成立的上行分支。**前一范围是作者在既有敏感性结果、较低预算与安特卫普妥协之间选定的规划目标，不是新做回归或独立舰册复算所得的置信区间。〔统2〕

为何仍给这个数量级？撤去安特卫普优势的旧和平试算，已把法国年度可动员舰数从111降到约71，对照英国120艘约为六成；英国增加准备、法国降低支出，还会进一步压低追赶速度。这个单项试验不能与预算降幅机械相乘，但足以否定把九成作为低成本常态。实现半数至三分之二也须逐年检查海员和整备；未达标，就缩减海外护航，不追加未经融资的建舰令。

年度可动员吨位并不等于同季集中，更不是胜算。法国将主力集中于欧洲近海、英国分担全球航路时，局部可以接近平衡；如果英国把远洋兵力调回，优势便重新向英国倾斜。到1848年，本文维持“法国具有局部拒止能力，英国具有全球持续部署优势”的主判，不把帆船时代的比例直接套进蒸汽与爆炸弹时代。'''),'选定可负担海军目标，把九成情景降为上行分支')
edit('02b_英国海权与和平_舰队海峡与帝国.md',lambda s:before(s,'### 3. 其他港口各有用途，不能在地图上直接相加','''安特卫普因而必须在交易中失去一部分军事价值，才可能充分兑现商业价值。本书拟议的首轮报价，是保留法国主权、商港和修理能力，**停止新增战列舰船台，限制平时完成配员的主力舰集中，禁止在河口集结对英登陆船团**；可用六艘在役战列舰作为初始谈判上限，而非宣称英国历史上曾接受这个数。新造与大规模调动事先通报，由双方认可的中立人员查验港册，英国相应停止通常封锁和商船捕获。另港建舰仍消耗同一海军预算，迁厂、运输和人员重建并不免费。

这项方案把商业增长放在新增舰队之前。英国仍可能认为法国控制低地本身就有危险，拒绝六艘上限而要求更彻底的军事撤除；此时法国应在更低上限和继续海战之间再作选择。主线优先降低安特卫普军事集中，保住城市与腹地；拒绝让步的分支则恢复持续海战成本。**不再同时领取“英国放心”和“河口保有最大进攻舰队”两项收益。**〔统4〕'''),'给安特卫普安排具体上限、监督、对价与失败退路')
edit('02b_英国海权与和平_舰队海峡与帝国.md',lambda s:s.replace('| 马耳他、爱奥尼亚 | 地中海部署、地区政治 | 取决于和谈年份、盟国安排与替代基地，不宜预判全部归英或全部归法 |','| 马耳他 | 中地中海补给与维修 | 主线承认英国实际驻军并以条约确认长期控制，交换通商与其他让步；恢复骑士团中立列次选 |\n| 爱奥尼亚 | 亚得里亚海入口与地方政治 | 以1807法国取得的权利为起点，转向本地自治与多方保证，限制外国常驻主力舰；直接法国军事占领列次选 |').replace('| 新加坡 | 马六甲通道、印度—中国贸易 | 1819 年以后是否按真实方式建立，取决于荷兰、公司及区域统治者关系 |','| 新加坡及马六甲海峡 | 印度—中国贸易的区域节点 | 英国保留槟榔屿并争取海峡南口商站；新加坡是首选候选，地方商站先于完整主权转让 |').replace('| 毛里求斯及若干糖岛 | 航路威胁、种植园贸易 | 比本土舰队与直布罗陀更有交换空间，但当地经济与驻军利益会阻碍简单交易 |','| 毛里求斯与波旁岛 | 印度洋补给、贸易与私掠 | 1807起点仍归法国；及早海上停战主线力保两岛但限制敌对私掠，战至1810以后则归还条件明显恶化 |'),'明确地中海和印度洋岛屿归属')
edit('02b_英国海权与和平_舰队海峡与帝国.md',lambda s:before(s,'### 8. 西属美洲：英国首先要的是入口，不一定是立即改旗','''到1848年，海峡节点的排序也应选定。法国保全荷兰并不意味着荷兰能够独占马六甲两端；英国已有槟榔屿，更可能在南端争取一处有地方统治者同意、与印度—中国航路相连的开放商站。**本文首选新加坡作为这一商站，次选继续依托槟榔屿并与荷兰商议马六甲准入；不把1824年式完整分界和主权转让自动保留。**这是根据地理、公司利益和地方权利竞争作出的排序，而非英国选择某一岛屿的必然定律。

史实提供了选择的机制：1819年安排首先允许公司设厂，1824年英荷交涉改变外部条件，此后苏丹与天猛公才签署更广的权利让渡。较强的荷兰外交地位会提高英国取得独占主权的价格，却未必消灭当地统治者利用英国贸易、津贴与竞争关系的动机。法国最划算的支持，是维护荷兰条约权与多方商业准入，而不是派出一支不存在于预算内的舰队替荷兰封死海峡。〔统5〕'''),'将新加坡从未决因素推进到1848节点排序')
